using System;
using System.Collections.Generic;
class Program {
    static void Main() {
        int[] nums = {3, 8, 1, 6, 7, 4};
        var chan = new List<int>();
        var le = new List<int>();
        foreach (int x in nums)
            (x % 2 == 0 ? chan : le).Add(x);
        Console.WriteLine("Chan: " + string.Join(" ", chan));
        Console.WriteLine("Le: " + string.Join(" ", le));
    }
}
